import { describe, expect, it } from "vitest";
import { FlowEdgeType, type FlowEdge, type FlowNode } from "../../types";
import { collectHighlightedEdges } from "./SkillBlockCanvas";

const node = (id: string) => ({ id }) as unknown as FlowNode;
const edge = (sourceId: string, targetId: string): FlowEdge => ({
  sourceId,
  targetId,
  type: FlowEdgeType.Auto,
});

describe("collectHighlightedEdges", () => {
  const nodes = [node("START"), node("reset_selection"), node("card_selection")];
  const edges = [edge("START", "reset_selection"), edge("reset_selection", "card_selection")];

  it("highlights the entry edge from START even when the trail omits it", () => {
    // Mantle call-frames enter an ordered block at its first real step, so the
    // stack trail has no START — the entry edge must still light up.
    const { highlightedEdges } = collectHighlightedEdges(nodes, edges, [
      "reset_selection",
      "card_selection",
    ]);
    const keys = highlightedEdges.map((e) => `${e.sourceId}->${e.targetId}`);
    expect(keys).toContain("START->reset_selection");
    expect(keys).toContain("reset_selection->card_selection");
  });

  it("does not prepend a second START when the trail already begins with it", () => {
    const { highlightedEdges } = collectHighlightedEdges(nodes, edges, [
      "START",
      "reset_selection",
    ]);
    const keys = highlightedEdges.map((e) => `${e.sourceId}->${e.targetId}`);
    expect(keys).toEqual(["START->reset_selection"]);
  });

  it("highlights nothing for an empty trail", () => {
    expect(collectHighlightedEdges(nodes, edges, []).highlightedEdges).toEqual([]);
  });
});
